import json
from websocket import create_connection
import time

def send_msg(ws, msg):
    ws.send(json.dumps(msg))
    return json.loads(ws.recv())

ws = create_connection('ws://web.chal.csaw.io:5000/websocket')
print("Connected to websocket")

# Initialize DDP connection
connect_msg = {
    "msg": "connect",
    "version": "1",
    "support": ["1"]
}

print("Connection response:", send_msg(ws, connect_msg))

# Try to register a new user
register_msg = {
    "msg": "method",
    "method": "createUser",
    "params": [{
        "username": "test_user_123",
        "password": "Test123!",
        "profile": {}
    }],
    "id": "1"
}

print("Registration response:", send_msg(ws, register_msg))

# Try to login
login_msg = {
    "msg": "method",
    "method": "login",
    "params": [{
        "user": {"username": "test_user_123"},
        "password": "Test123!"
    }],
    "id": "2"
}

print("Login response:", send_msg(ws, login_msg))

# Try to subscribe to users
sub_msg = {
    "msg": "sub",
    "name": "users",
    "params": [],
    "id": "3"
}

print("Subscription response:", send_msg(ws, sub_msg))

# Try to create a note
note_msg = {
    "msg": "method",
    "method": "notes.insert",
    "params": [{
        "title": "Test Note",
        "content": "This is a test note",
        "private": True
    }],
    "id": "4"
}

print("Note creation response:", send_msg(ws, note_msg))

# Try to list users
users_msg = {
    "msg": "method",
    "method": "users.list",
    "params": [],
    "id": "5"
}

print("Users list response:", send_msg(ws, users_msg))

# Listen for any responses
for _ in range(5):
    try:
        print("Received:", ws.recv())
        time.sleep(1)
    except:
        break

ws.close()

